"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Una distancia de inicio / fin convierte la pestaña en una pestaña parcial. Los demás perfiles cerrados del boceto se convierten en recortes en la placa. Agujeros y ventanas en una pestaña: centro a lo largo de la arista (en una arista curva, a lo largo del arco), centro desde el final del doblez, tamaño – también aparecen en el desarrollo. Si una arista curva pasa a su arista vecina sin quiebre y ambas tienen una pestaña con el mismo ángulo de doblez, las pestañas se unen sin corte de alivio. «Contorno de boceto» recorta de la pestaña los perfiles cerrados de un boceto: su X va a lo largo de la arista, su Y hacia dentro de la pestaña, y el origen está en el inicio de la arista, en el final del doblez (desplazable).",
