"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Seleccione todas las caras que deben desaparecer (en una cajera, paredes y fondo; en un agujero, la pared; en un empalme, la superficie redondeada). Las caras vecinas se prolongan sobre el hueco. El paso se recalcula al cambiar el cuerpo; la primera vez se carga para ello el núcleo geométrico completo (unos segundos).",
