"Darstellungsqualität":"Calidad de visualización",
"Das Bild konnte nicht gelesen werden.":"No se pudo leer la imagen.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"La imagen está colocada como plantilla en el plano. Ajuste después tamaño, posición, giro y opacidad en la ventana de propiedades (p. ej. el ancho según una medida conocida).",
"Das Ergebnis des Geometriekerns ist unlesbar":"El resultado del núcleo geométrico es ilegible",
"Das Ergebnis konnte nicht geschrieben werden":"No se ha podido escribir el resultado",
"Das Maß muss größer als 0 sein.":"La cota debe ser mayor que 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"La malla sigue siendo una malla de triángulos (no B-Rep). Edición en MALLA: Reparar, Reducir, Suavizar, Corte por plano … Las estrategias de fresado 3D de Fabricación pueden mecanizarla directamente.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"La malla tiene {0} triángulos. Cada uno se convierte en una cara del cuerpo: tarda mucho y vuelve lento el cuerpo. Suele ser mejor usar antes «Reducir».\n\n¿Convertir de todos modos?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"La malla no está cerrada. Ejecute primero «Reparar»: un cuerpo necesita una envolvente cerrada.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"La malla se extiende en Z de {0} a {1} mm, en X de {2} a {3} mm, en Y de {4} a {5} mm. Se eliminan los puntos que se desvían de una recta menos que la tolerancia.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"El perfil no debe cruzar el eje. Una línea abierta del boceto puede servir de eje.",
"Das Profil mit den jetzigen Werten überschreiben":"Sobrescribir el perfil con los valores actuales",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"El perfil se guía a lo largo de una línea o polilínea. Lo mejor es dibujar el perfil perpendicular al inicio de la trayectoria (p. ej. perfil en XZ, trayectoria en XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"El perfil se estampa en relieve o hundido a partir del plano del boceto.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"El material en bruto es el prisma que rodea el cuerpo seleccionado (más el desfase).",
"Das Setup hat keine Operationen.":"La configuración no tiene operaciones.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"La herramienta fresa en círculos cuyo centro se desplaza a lo largo de la ranura. Nunca está engastada en todo su ancho, lo que permite grandes profundidades de pasada y protege la fresa y el husillo. La fresa debería tener aproximadamente el 60 % del ancho de la ranura.",
"Das Werkzeug schneidet die Fläche nicht":"La herramienta no corta la superficie",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"La herramienta corta en dirección a las caras seleccionadas hasta alcanzar los sobremetales indicados.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"La herramienta penetra en vertical como una broca, fila por fila, hasta el modelo más el sobremetal. La fuerza de corte actúa a lo largo del husillo: adecuado para herramientas largas, cavidades profundas y máquinas poco rígidas. La herramienta debe cortar por el centro.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"La herramienta evita estas caras teniendo en cuenta las distancias de seguridad indicadas (garras, tornillo de banco).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"La herramienta evita estas caras mientras mecaniza las caras cercanas y respeta las distancias de seguridad.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"El primer Esc solo cancela la herramienta o la selección; un Esc de más no cierra el boceto",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Eso no es un agujero (empalme o espiga): haga clic en la pared interior de un agujero.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Eso no es un agujero (cara cilíndrica): haga clic en la pared del agujero.",
"Das ist keine WerkFab-Design-Datei.":"Este no es un archivo de tema de WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"No es una arista inclinada: haga clic en ambos extremos de la arista del chaflán.",
