"Drehen: C-Achse und angetriebenes Werkzeug ein":"Torneado: eje C y herramienta motorizada conectados",
"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Torneado: la pieza debe ser simétrica de revolución respecto al eje Z. Z0 = cara frontal arriba, X = diámetro.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Girar: hacer clic en el centro de giro y luego indicar el ángulo con el ratón (vista previa). Esc finaliza.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Torneado: diámetro en el que gira la torreta (Okuma, LinuxCNC). 0 = Ø del material en bruto + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Girar: seleccione elementos, haga clic en el punto de giro e indique el ángulo con el ratón (vista previa); también como copia",
"Drehen: Gewindeschnitt":"Torneado: pasada de roscado",
"Drehen: Gewindezyklus":"Torneado: ciclo de roscado",
"Drehen: Polar-Interpolation aus":"Torneado: interpolación polar desconectada",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Torneado: interpolación polar conectada (X diámetro, C en mm; vacío = X/C en grados)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Torneado: ciclo de acabado (contorno del ciclo de desbaste)",
"Drehen: Schruppzyklus ({contour} = Konturzeilen)":"Torneado: ciclo de desbaste ({contour} = líneas de contorno)",
"Drehen: Vorsatz erste Konturzeile":"Torneado: prefijo de la primera línea de contorno",
"Drehen: Vorsatz letzte Konturzeile":"Torneado: prefijo de la última línea de contorno",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"Girar: ángulo (°, sentido antihorario); centro de giro X; centro de giro Y; copias (0 = girar)",
"Drehen: Y-Achse aus":"Torneado: eje Y desactivado",
"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"Torneado: eje Y activado (plano X/Y; indique aquí también el bloqueo C de la máquina)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Torneado: Z delante de la cara frontal en el que gira la torreta. 0 = distancia de seguridad + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Torneado: interpolación cilíndrica desconectada",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Torneado: interpolación cilíndrica conectada ({cylr} = radio; vacío = Z/C sin)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Torneado: herramienta motorizada y eje C desconectados",
"Drehen: einen Winkel angeben.":"Girar: indicar un ángulo.",
"Drehgelenk":"Revolución",
"Drehgelenk angelegt – mit dem Regler bewegen.":"Junta de revolución creada: muévala con el control deslizante.",
"Drehgeschwindigkeit":"Velocidad de giro de la vista",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Torno con eje Y: las caras de llave, contornos y cajeras en la cara frontal se mecanizan con la pieza fija (C fijo) en X e Y, con más precisión que la interpolación polar. Lo que excede el recorrido Y se mantiene con interpolación polar.",
