"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Cuello extruido {0}: el agujero previo Ø {1} mm se ensancha hasta Ø {2} mm (factor {3}); el borde suele agrietarse.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Cuello extruido {0}: el agujero previo Ø {1} mm se ensancha hasta Ø {2} mm (factor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Cuello extruido {0}: está a {1} mm del borde (menos de 2 × el espesor de la chapa); el borde se abomba.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Cuello extruido {0}: demasiado alto para este agujero (el agujero previo se quedaría sin diámetro)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Cuello extruido: el borde de un agujero redondo se estira hacia arriba formando un collar, por ejemplo como cuello extruido para rosca. El diámetro del agujero del boceto es el diámetro interior acabado; en el desarrollo se corta el agujero previo, más pequeño.",
