"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Atajos personalizados: abrir el menú del grupo (▾) en la barra de herramientas, hacer clic en ⋮ junto al comando → «Cambiar atajo de teclado …».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Las cotas y notas propias se pueden arrastrar con el ratón en la hoja (distancia de la línea de cota, ángulo de la línea de directriz, radio del arco de ángulo). Dos clics en esquinas = cota de longitud. Clic en el borde de un círculo en la vista superior = diámetro (o radio). Ángulo: primero el vértice y luego un punto en cada lado. Chaflán: ambos extremos de la arista inclinada; da p. ej. 2×45°. El campo de texto tras cada cota contiene un complemento como ±0,1, H7 o 4×.",
