"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Una fresa redonda deja su radio en cada esquina interior, de modo que una pieza complementaria de aristas vivas no encaja. El alivio entra brevemente en la esquina y vuelve en cada esquina interior viva.{0}{1}",
