"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"La solevación necesita dos bocetos con perfiles cerrados en planos distintos.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"La solevación necesita dos bocetos con una curva cada uno (en planos distintos).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Solevación no posible – compruebe las secciones (un perfil cerrado cada una, sin torsión)",
