"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Haga clic primero en la cara del cuerpo que se mueve y después en la cara de destino del otro cuerpo. El cuerpo se gira y se desplaza hasta que el primer punto de clic quede sobre el segundo y las caras se apoyen una sobre otra.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Haga clic primero en la arista del cuerpo que se mueve y después en la arista de destino del otro cuerpo. Las aristas rectas quedan coincidentes (centro sobre centro); en las aristas circulares (agujero y espiga) los ejes se orientan igual y los centros se unen.",
"Erst ein Setup anlegen.":"Cree primero una configuración.",
