"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Haga clic en una cara de un cuerpo: su borde se añade al boceto como contorno. Un clic en una arista proyecta solo esa arista (los círculos siguen siendo círculos). La geometría proyectada es violeta.",
"Fläche ersetzen":"Sustituir cara",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Sustituir cara: llevar una cara plana a otro plano; el cuerpo crece o se acorta",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Fondo detrás de las ventanas – se aplica si arriba se elige el tema «Personalizado»",
"Fläche löschen":"Eliminar cara",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Eliminar cara: quitar agujeros, cajeras, empalmes o chaflanes; las caras vecinas cierran el hueco",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Mostrar en color la cara o arista bajo el puntero",
"Fläche versetzen":"Desfasar cara",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Desfasar cara: desplazar caras planas, cambiar el diámetro de agujeros y pivotes",
"Fläche wählen":"Seleccionar cara",
"Fläche wählen, die getrimmt wird":"Seleccione la superficie que se recortará",
"Fläche zum Antasten in Z":"Cara para palpar en Z",
"Fläche {0}":"Cara {0}",
"Flächen":"Caras",
"Flächen (alle Kanten ringsum)":"Caras (todas las aristas del contorno)",
"Flächen (aufeinander legen)":"Caras (apoyar una sobre otra)",
"Flächen am Körper":"Caras del cuerpo",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Caras planas en el extremo de la pieza (dos planos, cuadrado, hexágono) con una fresa de vástago motorizada a lo largo de Z. Ancho entre caras = el doble de la distancia de la cara al eje de giro. X y C se mueven juntos (interpolación polar, Fanuc G12.1); sin esta plantilla en el postprocesador se emiten pasos cortos X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Haga clic en las caras a las que se dará espesor (un nuevo clic las quita).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Haga clic en las caras a las que aplicar ángulo de desmoldeo (otro clic las quita).",
"Flächen anklicken, die offen sein sollen.":"Haga clic en las caras que deben quedar abiertas.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Haga clic en las caras que se desfasarán (un nuevo clic las quita).",
"Flächen im Modell":"Caras del modelo",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"Las superficies con aristas comunes se unen en una sola. Si la envolvente queda cerrada por completo, se obtiene un cuerpo sólido (editable después con normalidad). Los huecos mayores que la tolerancia permanecen abiertos.",
