"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Líneas rectas del boceto que no pertenecen a ningún perfil (también líneas auxiliares). Plegado: la línea es el centro de la zona de plegado y el boceto allí es el desarrollo; la parte más grande de la placa permanece en su sitio y todo lo que queda más allá de la línea gira junto con sus pestañas. La línea vale para toda la placa. Nervio: una costilla a lo largo de la línea, redonda en la sección y en los extremos; la chapa conserva su espesor.",
