"Geschlossen (Gehrung)":"Cerrada (inglete)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Cerrada: las pestañas de dos aristas contiguas llegan hasta la bisectriz de la esquina y dejan ahí la holgura. El alivio de esquina se sitúa donde se cruzan las zonas de plegado, tanto en el desarrollo como en la pieza plegada. Una pestaña en una arista curva también se corta a inglete en una esquina real (allí sin alivio de esquina).",
