"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Los perfiles cerrados se convierten en superficies planas, p. ej. tapa y fondo, para coser después las superficies en un cuerpo.",
