"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"En la imagen simétrica la herramienta gira al revés: el fresado en concordancia pasa a ser fresado en oposición. La corrección de radio del control también cambia de lado.",
