"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Los cuerpos importados no tienen historial de diseño, pero pueden seguir editándose (empalme, chaflán, corte …) y usarse para CAM. Con «Eje Y hacia arriba» los modelos de programas con Y hacia arriba se colocan correctamente.",
