"J (relativ)":"J (relativo)",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"La primera curva de cada boceto, abierta o cerrada. Las curvas se unen mediante una piel (superficie sin espesor).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Un archivo por plancha. La trayectoria discurre junto al contorno, en el desecho, a media anchura de corte (en fresado, medio diámetro de fresa); los recortes van antes del contorno de su pieza y cada contorno comienza con una entrada desde el desecho. Encendido con M3 (láser: M3 S…), apagado con M5, tiempo de perforación como G4. El origen es la esquina inferior izquierda de la plancha; en fresado, Z0 es la cara superior de la chapa. Compruebe el programa en la máquina o en un simulador CNC antes de usarlo.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Cada eje por separado: haga clic en una arista, una esquina, una cara o un agujero. Los ejes sin definir se toman del punto del material en bruto.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Cada operación como subprograma (LBL) al final del programa, llamada con CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Cada círculo del boceto es el centro de un agujero. Se taladra en sentido contrario a la normal del boceto (hacia el material).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Cada círculo del boceto se repite girándolo alrededor del centro (en coordenadas del boceto): un círculo a la distancia del radio del círculo primitivo da un círculo de agujeros.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Cada círculo del boceto se convierte en una cuadrícula: separaciones en X e Y del boceto (también negativas).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Ahora un punto en el segundo lado.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Ahora cada dirección una vez hasta el tope: deslizar, tirar, pulsar, inclinar, girar (10 s) …",
