"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Calibrar: haga clic en dos puntos de la imagen cuya distancia conozca e introduzca la distancia real: la imagen recibe la escala correcta.",
