"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Arista {0}: un ángulo de plegado superior a 180° no se puede fabricar.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Arista {0}: pestaña en una arista curva – su borde se comprime un {1} % al conformar (riesgo de arrugas); el recorte es allí una aproximación.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Arista {0}: pestaña en una arista curva – su borde se estira un {1} % al conformar (riesgo de grietas); el recorte es allí una aproximación.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Arista {0}: la medida de la pestaña {1} mm es menor que el plegado ({2} mm)",
