"Kante {0}: die Abstände lassen keine Lasche übrig.":"Arista {0}: las distancias no dejan ninguna pestaña.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Arista {0}: la pestaña cruza una línea de plegado; haga que termine antes del plegado con «Distancia inicio / fin»",
"Kante {0}: die Lasche liegt in einer Biegezone":"Arista {0}: la pestaña está en una zona de plegado",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Arista {0}: un recorte pertenece a una pestaña que no existe.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Arista {0}: un recorte en la pestaña está a {1} mm del pliegue (menos de 2 × el espesor de chapa) – se deforma al plegar.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Arista {0}: un recorte está a {1} mm del pliegue (menos de 2 × el espesor de la chapa): se deforma al plegar.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Arista {0}: un recorte sobresale de la pestaña.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Arista {0}{1}: la pestaña de {2} mm es más corta que 2 × el espesor de la chapa: apenas se puede plegar en la plegadora.",
