"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Soltar la tapa y elegir «Calibrar punto cero». Después probar cada dirección: la barra debe moverse y, en reposo, permanecer en la zona muerta gris.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Deslizar la tapa = desplazar, pulsar/tirar = zoom, inclinar y girar = girar el modelo. En los bocetos solo desplazar y zoom. SpaceMouse Pro/Enterprise: T, F, R = vista superior, frontal, derecha. Si no ocurre nada: cerrar brevemente el controlador de 3Dconnexion y volver a conectar.",
