"Konturen außen und innen":"Contornos exteriores e interiores",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Los contornos siguen el borde de las áreas oscuras. La línea central recorre el medio de los trazos: adecuada para grabados y dibujos a línea. «Rectas, arcos y círculos» detecta aristas rectas, esquinas vivas, redondeos y círculos; «Polilíneas» sigue la imagen punto por punto. Después ajuste la escala si es necesario con «Calibrar plantilla» o «Escalar».",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Los contornos con compensación de radio en el control (RL/RR) se abordan y abandonan con APPR/DEP; el control calcula por sí mismo el punto auxiliar y la compensación",
