"Kurven":"Curvas",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Curvas de un boceto sobre la cara frontal (transversal al eje de giro) con una fresa motorizada a lo largo de Z (X y C se mueven juntos; Fanuc: interpolación polar G12.1). Las curvas abiertas se fresan de ida y vuelta. Profundidad desde la cara frontal.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Las curvas de un boceto situado a lo largo del eje de giro se enrollan sobre la circunferencia y se fresan con una fresa motorizada dirigida hacia el eje (Z y C se mueven juntos; Fanuc: interpolación cilíndrica G7.1). El plano del boceto determina el ángulo en el que se sitúa el contorno; los tramos horizontales del boceto se convierten en arcos alrededor de la pieza. Profundidad desde el diámetro exterior.",
"Kurzbefehl":"Atajo",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Los recorridos cortos (hasta la distancia de mantenimiento) se hacen abajo con el avance de transición en lugar de pasar por la altura de retirada; sin comprobación de colisiones, así que manténgala pequeña.",
