"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Elija el material en la configuración, en «Material en bruto → Material del bruto». La densidad determina el peso del material en bruto, Vc es un valor orientativo para metal duro; el color se muestra en la simulación.",
