"Mehrere Schlichtdurchgänge":"Varias pasadas de acabado",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Varias aristas consecutivas cuentan como un único recorrido: el radio varía desde el inicio de la cadena hasta su final y los puntos de control se dan en % de la longitud total de la cadena. Lo calcula el núcleo geométrico completo.",
