"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Con puntos de control, el radio pasa por los valores indicados (posición en % de la longitud de la arista). Lo calcula el núcleo geométrico completo; la primera vez tarda unos segundos en cargarse.",
"Mit dem 3D-Taster kann nicht zerspant werden":"El palpador 3D no puede utilizarse para mecanizar",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Comparar con la pieza terminada: verde = a cota, azul = material restante, rojo = demasiado profundo",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Mover el ratón junto a un contorno (el lado determina la dirección) · Esc finaliza",
"Mit diesem Werkzeug kann nicht gefräst werden":"Con esta herramienta no se puede fresar",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Con un macho de roscar usar solo el ciclo «Roscado con macho» – un ciclo de taladrado lo rompería",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Con varias pasadas, la profundidad de la rosca se fresa en etapas que arrancan aproximadamente la misma cantidad cada una; protege las fresas de roscar pequeñas y los materiales duros. La pasada en vacío recorre la última trayectoria otra vez sin pasada adicional.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Con «Ciclos de taladrado» en el programa NC se emiten ciclos del control (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85); de lo contrario, movimientos desarrollados.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Con «Conservar original», el original y su imagen simétrica forman una sola malla; los puntos situados en el plano de simetría se unen, de modo que una mitad abierta se convierte en una pieza cerrada.",
