"Nur Skizze":"Solo boceto",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Mecanizar solo lo que una fresa mayor ha dejado en las esquinas.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Repasar solo las zonas del contorno que una fresa mayor no ha alcanzado (esquinas interiores, zonas estrechas). Sin arcos de entrada/salida, puentes de sujeción ni pasadas de acabado; compensación en el ordenador.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Solo donde no llegó la herramienta de referencia: zonas planas en paralelo, zonas empinadas como línea de nivel. Con una herramienta de la lista también cuenta su forma; por ejemplo, lo que una fresa tórica deja en los acuerdos.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Solo las caras planas pueden servir como plano de boceto.",
