"Nut liegt nicht am Teil":"La ranura no está en la pieza",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Ranura a lo largo del eje de giro (p. ej. chavetero) con una fresa motorizada dirigida hacia el eje; el husillo principal sujeta la pieza como eje C. Ancho de ranura = Ø de fresa. Inicio/final Z en Z del modelo; si la ranura llega hasta la cara frontal, la fresa entra por delante; si no, penetra en el inicio. Profundidad desde el diámetro exterior.",
