"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Las aristas abiertas se muestran en rojo. «Reparar» cierra los huecos.",
"Offene Linie in einer Skizze wählen":"Seleccione una línea abierta en un boceto",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Las curvas abiertas o cerradas se extruyen perpendicularmente al boceto: el resultado es una superficie (pared sin espesor). Con «Engrosar» o «Coser» se convierte en un volumen.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Las curvas abiertas o cerradas se giran alrededor del eje: el resultado es una superficie, no un volumen.",
