"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Sin «Modelada», la rosca solo se representa (rápido). Si está modelada, la forma de la rosca se corta realmente, p. ej. para impresión 3D. Agujero para M8 = Ø6,8.",
