"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 no van allí a coordenadas de máquina (G53 anula la corrección de longitud de herramienta) – retirada a la altura de seguridad, sin recorrido de referencia XY",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: no se emite función de suavizado (G5.1 es de Fanuc) – ajuste Hi-Cut/Super-NURBS en la máquina",
