"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Proyectar (J): haga clic en una cara o arista de un cuerpo; su proyección se añade al boceto",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"Proyectar aristas y caras necesita un sólido del núcleo estándar; la silueta del cuerpo y las curvas de intersección también funcionan con mallas.",
