"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Estampado {0}: el contorno es más estrecho que 2 × el espesor de chapa – no queda ninguna cavidad.",
"Prägung {0}: lässt sich so nicht formen":"Estampado {0}: no se puede conformar así",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Estampado {0}: {1} mm supera 3 × el espesor de chapa – con pared vertical la chapa se rompe.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Estampado: el contorno no se recorta, sino que se presiona fuera de la placa según la altura indicada. Avellanado embutido: el borde de un agujero redondo se presiona hasta formar un cono de 90° – para tornillos de cabeza avellanada en chapa fina (− hacia abajo: tornillo desde arriba).",
