"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Desbasta en 4 ejes simultáneos de fuera hacia dentro: una espiral alrededor del eje A por pasada (alternando en +X y −X), nunca más profundo que la pieza más el sobremetal. Con fresa de vástago o esférica.",
