"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Cajera en la circunferencia a partir de los contornos cerrados de un boceto situado a lo largo del eje de torneado (los contornos interiores permanecen como islas). El boceto se enrolla sobre el diámetro; una fresa de punta plana motorizada orientada hacia el eje desbasta de dentro hacia fuera (Z y C se mueven conjuntamente; Fanuc: interpolación cilíndrica G7.1). La fresa penetra en rampa a lo largo del anillo más interior.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Cajera en la cara frontal a partir de los contornos cerrados de un boceto (los contornos interiores permanecen como islas), con una fresa de vástago motorizada a lo largo de Z. El vaciado va de dentro hacia fuera; la fresa penetra en rampa a lo largo de la trayectoria más interior y permanece abajo dentro de un nivel. X y C se mueven juntos (Fanuc: interpolación polar G12.1). Profundidad desde la cara frontal.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Cajera con isla – el ciclo del control no admite islas",
"Tasche schmaler als das Werkzeug":"Cajera más estrecha que la herramienta",
