"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Opera realmente dos mallas cerradas entre sí: las caras interiores desaparecen y las aristas de corte se vuelven a mallar. Solo se calcula donde las dos mallas pueden encontrarse, por lo que una malla grande con una intervención pequeña es rápida. Si dos mallas grandes se solapan por completo, use antes «Reducir».",
