"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Enrolla las curvas del boceto sobre el cilindro: X sigue siendo X, la distancia transversal al eje se convierte en un arco sobre el Ø de desarrollo (giro A). El boceto debe ser paralelo al eje A, p. ej. sobre un plano tangente. Se fresa a profundidad fija bajo la superficie de la pieza; para grabados, rótulos y ranuras alrededor de la pieza.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Como el contorno 3D, pero la herramienta desciende de forma continua sin escalones; sin marcas de penetración en paredes empinadas.",
