"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"«+» = se creará la herramienta. Los datos de corte son valores orientativos para metal duro ({0}){1}; refrigeración: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"«Encajar unos en otros» coloca los recortes en los huecos y entrantes de sus vecinos y en los recortes de estos (sin girar 90°, solo volteados 180°); la distancia nunca se reduce. Sin la marca, se colocan en filas según su rectángulo envolvente. Con «Boceto + cuerpos» se crean cuerpos planos del espesor de la chapa, que en la fabricación se pueden cortar con contorno 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"«Interior/Exterior» necesita contornos cerrados – fresar las curvas abiertas con «Sobre la curva»",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"«Terminar boceto» → Extrusión, Revolución o Agujero.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"«Boceto» → elegir el plano XY/XZ/YZ o hacer clic en una cara plana.",
