"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ Comprobar cada programa NC antes de su primera ejecución: en la máquina en una marcha en vacío (bloque a bloque, avance rápido reducido) o en un simulador NC externo. La simulación aquí no lo sustituye – uso bajo su propia responsabilidad, sin garantía.",
