"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ Tras el último cambio del cuerpo no quedó claro a qué arista o cara se refiere. Compruébelo y, si es necesario, elimínelo y proyecte de nuevo.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ La lógica del programa (JavaScript) no se ejecuta: revise las funciones especiales, el 4.º/5.º eje, los ciclos de medición y las opciones de máquina en el editor de postprocesador.",
